import {React, useState} from "react";
import {useStateMachine} from "little-state-machine";
import {Link} from "react-router-dom";
import './theme.css';
import './HomePage.css';
import {languages, locale_text} from "./lang";


export function HomePage({setGlobalLanguage}) {

    const {actions, state} = useStateMachine({
        changeLanguage: (state, payload) => {
            console.log(state, payload)
            return ({...state, 'language': payload});
        }
    });

    const [currentLanguageState, setLanguageState] = useState(state['language']);
    const lang = currentLanguageState;

    return (<>
        <div>
            <img src="/logo.png" alt="logo" className="logo"/>
            <nav>
                <ul className="navbar">
                    {
                        Object.entries(languages).map(([key, value]) => {
                            const isSelected = (lang === value);
                            const isSelectedClass = isSelected ? "nav-li-selected" : "";
                            const targetLanguage = value;
                            const setLanguage = () => {
                                actions.changeLanguage(targetLanguage);
                                setLanguageState(targetLanguage);
                                setGlobalLanguage(targetLanguage);
                            };

                            return (
                                <li key={value}>
                                    <a className={isSelectedClass} onClick={setLanguage}>{key}</a>
                                </li>
                            )
                        })
                    }
                </ul>
            </nav>
        </div>


        <div className="container-page-root">
            <h1 className="title-text title-text-h1 title-text-h1-homepage">
                {locale_text(lang, 'home-page-title')}
            </h1>
            <h2 className="title-text title-text-h2 title-text-h2-homepage">
                {locale_text(lang, 'home-page-subtitle')}
            </h2>
            <p className="description-text">
                {locale_text(lang, 'home-page-description')}
            </p>

            <Link to="/surveycity">
                <button className="button-generic button-start-survey">
                    {locale_text(lang, 'home-page-button-start-survey')}
                </button>
            </Link>


            <div className="home-footer-section">
                <p className="author-text">
                    <span className="title-text-green author-text-title">
                        {locale_text(lang, 'home-page-author-title')}
                    </span> <br/>
                    MIT Senseable City Lab, Korea Advanced Institute of Science and Technology
                </p>

                <div className="grid-container grid-container-align-bottom" dir={"ltr"}>
                    <div className="grid-item">
                        <img className="home-org-icon" src="/org-mit.png" alt="mit" width="auto" height="24px"/>
                    </div>
                    <div className="grid-item">
                        <img className="home-org-icon" src="/org-kaist.svg" alt="kaist" width="auto"
                             height="40px"/>
                    </div>

                </div>
            </div>

        </div>

        {/*<footer>*/}
        {/*    <a href={"https://github.com/GindaChen"}>CopyRight © 2023 @GindaChen</a>*/}
        {/*</footer>*/}
    </>)
        ;
}
